        private static Dictionary<string, Geometry> Build() {
            var built = new Dictionary<string, Geometry>(StringComparer.OrdinalIgnoreCase);
            foreach (KeyValuePair<string, Func<Geometry>> source in Sources) {
                Geometry geometry = source.Value();
                geometry.Freeze();
                built[source.Key] = geometry;
            }
            return built;
        }

        private static Geometry Symbol(string data, double rotate = 0) {
            Geometry geometry = Geometry.Parse(data).Clone();
            var transform = new TransformGroup();
            if (rotate != 0) {
                transform.Children.Add(new RotateTransform(rotate, 480, -480));
            }

            transform.Children.Add(new TranslateTransform(0, 960));
            transform.Children.Add(new ScaleTransform(Box / 960, Box / 960));
            geometry.Transform = transform;
            return geometry;
        }
